const lines=['第一站：做一个让伙伴认识你的个人主页。','需要线索？去锦囊里找找。','作品不必一次完成，先交出第一版。','看看同行者的作品，留一条具体建议。'];
let lineIndex=0;
const crest=`<svg class="crest" viewBox="0 0 48 48" aria-hidden="true" shape-rendering="crispEdges"><path fill="#cfaa62" d="M22 0h4v8h4v4h8v4H28v8h-8v-8H10v-4h8V8h4z"/><path fill="#5b809c" d="M8 46V26h4v-6h6v-4h12v4h6v6h4v20h-8V28h-4v-4h-8v4h-4v18z"/><path fill="#cfaa62" d="M4 44h40v4H4z"/></svg>`;
const warrior=`<svg viewBox="0 0 64 96" class="warrior-sprite" shape-rendering="crispEdges" aria-hidden="true"><ellipse cx="32" cy="91" rx="23" ry="3" fill="#26446433"/><g class="cape"><path fill="#345b89" d="M18 28h28v10h4v14h4v16h4v16H10V68h4V48h4z"/><path fill="#6c9dc1" d="M18 38h8v36h-4v10H10V68h4V48h4z"/><path fill="#4877a4" d="M42 35h4v18h4v16h4v12H42z"/></g><path fill="#34465c" d="M24 65h8v20h-2v6H19v-5h5zM35 65h8v20h4v6H35z"/><path fill="#ebf4f4" d="M23 34h17v7h6v20h-5v10H23V60h-5V41h5z"/><path fill="#9cb9cb" d="M23 41h5v15h13v7H23zM38 35h4v21h-5z"/><path fill="#d1ab65" d="M22 60h20v5H22zM28 61h6v6h-6z"/><path fill="#d6b28c" d="M25 17h15v14H25zM16 48h6v10h-6zM43 48h6v10h-6z"/><path fill="#345b89" d="M25 7h13v4h6v18h-5V17H25v13h-5V13h5z"/><path fill="#8cb4cc" d="M25 7h13v4H25zM21 13h4v10h-4z"/><path fill="#383e50" d="M28 20h3v3h-3zM36 20h3v3h-3z"/><path fill="#dfbc75" d="M19 32h7v5h-7zM37 32h7v5h-7z"/><path fill="#526b85" d="M48 43h3v37h-3z"/><path fill="#f7f4dc" d="M49 47h3v29h-3z"/><path fill="#c4a163" d="M44 42h12v4H44zM48 35h4v7h-4z"/></svg>`;
navs[0][2]='冒险大厅';
const previousShell=shell;
shell=function(){return previousShell().replace(/<canvas[^>]*class="brand-mark"[^>]*><\/canvas>/,crest);};
const previousHome=home;
home=function(){let s=previousHome();const a=s.indexOf('<section class="hero">'),z=s.indexOf('</section>',a)+10;s=s.slice(a,z).length? s.slice(z):s;return `<section class="daylight-hero"><img src="assets/daylight-valley.png" alt="白昼中的白石山城与瀑布"><div class="scene-caption">AI BUILDER SCHOOL <span>第一章 · 相识与表达</span></div><button class="warrior" id="warrior-talk" aria-label="与斗篷战士互动，切换向导提示">${warrior}<span>点击角色 · 听下一句</span></button><div class="speech"><span class="speaker">旅途向导 <small id="speech-count">${lineIndex+1} / 4</small></span><p id="speech-line" aria-live="polite">${lines[lineIndex]}</p><button class="primary" data-action="task">查看本周任务 →</button></div></section>`+s;};
document.addEventListener('click',e=>{if(e.target.closest('#warrior-talk')){lineIndex=(lineIndex+1)%lines.length;document.querySelector('#speech-line').textContent=lines[lineIndex];document.querySelector('#speech-count').textContent=`${lineIndex+1} / 4`;}});
const oldPaintAvatar=paintAvatar;
paintAvatar=function(c,n){if(n!==0)return oldPaintAvatar(c,n);const x=c.getContext('2d');x.clearRect(0,0,24,24);x.fillStyle='#dcecf3';x.fillRect(0,0,24,24);x.fillStyle='#426c96';x.fillRect(6,4,12,16);x.fillRect(3,14,18,10);x.fillStyle='#e5bc96';x.fillRect(9,8,6,7);x.fillStyle='#e5eff3';x.fillRect(8,16,8,8);x.fillStyle='#cfac69';x.fillRect(5,16,4,3);x.fillRect(15,16,4,3);x.fillStyle='#384e68';x.fillRect(9,10,2,2);x.fillRect(13,10,2,2);};
render();
